base={(0,0),(0,1),(0,2),(1,1),(2,1)}
def transforms(s):
 out=set()
 for reflect in [False,True]:
  for k in range(4):
   pts=[]
   for r,c in s:
    if reflect:c=-c
    for _ in range(k):r,c=c,-r
    pts.append((r,c))
   mr=min(r for r,c in pts); mc=min(c for r,c in pts)
   out.add(frozenset((r-mr,c-mc) for r,c in pts))
 return out
shapes=transforms(base); len(shapes),shapes

union=set(); occ=[]
for s in shapes:
 h=max(x for x,y in s)+1; w=max(y for x,y in s)+1
 for i in range(13-h+1):
  for j in range(13-w+1):
   cells={(i+x,j+y) for x,y in s}
   if all(g[x][y]==0 for x,y in cells):occ.append(cells);union|=cells
len(occ),len(union),sorted(union)
